import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353L;
    static final int MAX_N = 2 * 100000 + 1;
    static long[] fac = new long[MAX_N + 1];
    static long[] facInv = new long[MAX_N + 1];

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        fac[0] = 1;
        for (int i = 1; i <= MAX_N; i++) {
            fac[i] = fac[i - 1] * i % MOD;
        }

        facInv[MAX_N] = modPow(fac[MAX_N], MOD - 2, MOD);
        for (int i = MAX_N; i >= 1; i--) {
            facInv[i - 1] = facInv[i] * i % MOD;
        }

        long ans;
        if (n - 3 > 0) {
            ans = mod_nCr(m, n - 1) * (n - 2) % MOD * modPow(2, n - 3, MOD) % MOD;
        } else {
            ans = mod_nCr(m, n - 1) * (n - 2) % MOD;
        }
        ans %= MOD;
        System.out.println(ans);
    }

    static long mod_nCr(int n, int r) {
        if (n < r || n < 0 || r < 0) return 0;
        long tmp = facInv[n - r] * facInv[r] % MOD;
        return tmp * fac[n] % MOD;
    }

    static long modPow(long base, long exp, long mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) res = res * base % mod;
            base = base * base % mod;
            exp >>= 1;
        }
        return res;
    }
}

